document.querySelectorAll(".code__copy").forEach(function(e){e.hidden=!1,e.addEventListener("click",async function(){var t,n=e.closest("figure").querySelector("code").textContent;try{await navigator.clipboard.writeText(n)}catch{t=document.createElement("textarea"),t.value=n,document.body.append(t),t.select();try{document.execCommand("copy")}catch{}t.remove()}e.textContent="Copied",setTimeout(function(){e.textContent="Copy"},1500)})})